package org.financial.petsfactory;

public class Cat implements Pet {
    public String makeSound() {
        return "Miau";
    }
}

package org.financial.petsfactory;

public class CatFactory implements PetFactory {
    public Pet createPet() {
        return new Cat();
    }
    public PetFood createPetFood() {
        return new CatFood();
    }
}

package org.financial.petsfactory;

public class CatFood implements PetFood {
    public String getType() {
        return "Ração de gato";
    }
}

package org.financial.petsfactory;

public class Dog implements Pet {
    public String makeSound() {
        return "Au Au";
    }
}

package org.financial.petsfactory;

public class DogFactory implements PetFactory {
    public Pet createPet() {
        return new Dog();
    }
    public PetFood createPetFood() {
        return new DogFood();
    }
}

package org.financial.petsfactory;

public class DogFood implements PetFood {
    public String getType() {
        return "Ração de cachorro";
    }
}

package org.financial.petsfactory;

public interface Pet {
    String makeSound();
}

package org.financial.petsfactory;

public class PetClient {
    private Pet pet;
    private PetFood food;

    public PetClient(PetFactory factory) {
        pet = factory.createPet();
        food = factory.createPetFood();
    }

    public String getPetSound() {
        return pet.makeSound();
    }

    public String getPetFoodType() {
        return food.getType();
    }
}

package org.financial.petsfactory;

public interface PetFactory {
    Pet createPet();
    PetFood createPetFood();
}

package org.financial.petsfactory;

public interface PetFood {
    String getType();
}

